  background("#f4efe4");
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fill("#7fb2d9", 180);
  brush.beginShape(0.3);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 200);
  brush.vertex(0, 200);
  brush.endShape(true);
  brush.fill("#d1495b", 220);
  brush.circle(200, 150, 60);

  // Drawing a sunset across the canvas
  const sunsetColor = "#0056b3";
  const sunsetDistance = 500;
  const sunsetHeight = 500;

  for (let x = 0; x < width; x++) {
    let y = sunsetHeight;
    for (let i = 0; i < sunsetDistance; i++) {
      const distance = Math.sqrt(x * x + y * y);
      const angle = Math.atan2(y, x);
      if (distance <= sunsetDistance && angle < Math.PI / 2) {
        let r = Math.sqrt(sunsetColor.length - 2 * sunsetColor.length * Math.sin(angle));
        brush.fill(sunsetColor, 120);
        brush.circle(x, y, r);
        y -= sunsetHeight;
      }
    }
  }

  brush.endShape(true);
}

